def mark_read_documents_processed(apps, schema_editor):
    """Documents uploaded before this change whose text was read (they
    have passages) count as processed. Run "manage.py reprocess_documents"
    afterwards to give their passages section names too."""
    Document = apps.get_model("documents", "Document")
    for document in Document.objects.filter(passage_count__gt=0):
        document.processed_at = document.uploaded_at
        document.save(update_fields=["processed_at"])


